  v1.route("/oma/me", buildMeRoutes({
    services,
    authDisabled,
    loadTenant: async (tenantId) => {
      const r = await sql
        .prepare(`SELECT id, name FROM "tenant" WHERE id = ?`)
        .bind(tenantId)
