        .prepare(
          `SELECT t.id AS id, t.name AS name, m.role AS role, m.created_at AS created_at
             FROM "membership" m JOIN "tenant" t ON t.id = m.tenant_id
            WHERE m.user_id = ? ORDER BY m.created_at ASC, t.id ASC`,
